```css
.wcc {
    --wc-primary: #409EFF; /* 主题色 */

    /* 浅色主题 */
    --wc-bg-light: #FFF; /* 主背景色 */
    --wc-title-color-light: #333; /* 左上角日期标题 */
    --wc-title-sub-color-light: #7A7A7A; /* 左上角日期标题的右侧描述 */
    --wc-opt-color-light: #409EFF; /* 视图控制条主色 */
